import java.util.*;

class Solution {
  public List<List<Integer>> permuteUnique(int[] nums) {
    Arrays.sort(nums);
    List<List<Integer>> ans = new ArrayList<>();
    build(nums, new boolean[nums.length], new ArrayList<>(), ans);
    return ans;
  }

  private void build(int[] nums, boolean[] used, List<Integer> cur, List<List<Integer>> ans) {
    if (cur.size() == nums.length) {
      ans.add(new ArrayList<>(cur));
      return;
    }
    for (int i = 0; i < nums.length; i++) {
      // among equal values, only take them in index order to avoid duplicate permutations
      if (used[i] || (i > 0 && nums[i] == nums[i - 1] && !used[i - 1])) continue;
      used[i] = true;
      cur.add(nums[i]);
      build(nums, used, cur, ans);
      cur.remove(cur.size() - 1);
      used[i] = false;
    }
  }
}
